) AS v(username, title, start_date, end_date, people, transports, status, started_at, finished_at)
JOIN member m ON m.username = v.username
WHERE NOT EXISTS (SELECT 1 FROM trip t WHERE t.member_id = m.member_id AND t.title = v.title AND t.start_date = v.start_date);

-- 일정 칸: 이름·분류·주소·좌표는 retrip_place에서 그대로 복사. 칸이 아직 없는 여행에만
INSERT INTO trip_stop (trip_id, day_no, place_id, name, category, address, lat, lng, start_time, stay_min, state, importance, arrived_at, departed_at)
SELECT t.trip_id, v.day_no, p.id, LEFT(p.name, 120),
  LEFT(COALESCE(NULLIF(p.biz_type, ''), CASE p.content_type_id WHEN '12' THEN '관광지' WHEN '14' THEN '문화시설' WHEN '15' THEN '축제·행사'
    WHEN '28' THEN '레포츠' WHEN '32' THEN '숙박' WHEN '38' THEN '쇼핑' WHEN '39' THEN '음식점' ELSE '관광지' END), 60),
  LEFT(p.address, 200), p.latitude, p.longitude, v.start_time, v.stay_min, v.state, v.importance, v.arrived_at, v.departed_at
