) AS v(username, title, start_date, day_no, place_id, start_time, stay_min, state, importance, arrived_at, departed_at)
JOIN member m ON m.username = v.username
JOIN trip t ON t.member_id = m.member_id AND t.title = v.title AND t.start_date = v.start_date
JOIN retrip_place p ON p.id = v.place_id
WHERE NOT EXISTS (SELECT 1 FROM trip_stop x WHERE x.trip_id = t.trip_id);

COMMIT;
